#!/usr/bin/env python3
"""Render offline follow-up using frozen results and actual MCP snapshots; no network."""
import json,hashlib,base64,html
from pathlib import Path
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
def save(p,x):Path(p).write_text(json.dumps(x,indent=2,allow_nan=False,default=str))
r=json.loads(Path('followup_results.json').read_text());prior=json.loads(Path('followup_preservation.json').read_text());memory=json.loads(Path('followup_memory_retrieval.json').read_text());old_sources=json.loads(Path('source_index.json').read_text());new=[];trials=[]
for p in sorted(Path('mcp_artifacts').glob('*/manifest.json')):
 if str(p) in prior:continue
 m=json.loads(p.read_text());assert m['kind'] in ('trial_search','trial_detail')
 for f,v in m['files'].items():assert sha(p.parent/f)==v['sha256']
 new.append({'path':str(p),'manifest_sha256':sha(p),**m})
 if m['kind']=='trial_detail':
  raw=json.loads((p.parent/'response.json').read_text());pro=raw['protocolSection'];st=pro['statusModule'];de=pro['designModule'];id=pro['identificationModule']['nctId']
  trials.append({'nct_id':id,'title':pro['identificationModule']['briefTitle'],'purpose':de.get('designInfo',{}).get('primaryPurpose'),'phase':de.get('phases',[]),'status':st['overallStatus'],'status_verified_date':st.get('statusVerifiedDate'),'last_update_posted':st['lastUpdatePostDateStruct']['date'],'retrieved_at':m['retrieved_at'],'enrollment':de.get('enrollmentInfo'),'has_results':bool(raw.get('resultsSection')),'url':'https://clinicaltrials.gov/study/'+id,'raw_source':str(p.parent/'response.json'),'raw_sha256':sha(p.parent/'response.json'),'interventions':pro.get('armsInterventionsModule',{}).get('interventions',[]),'primary_outcomes':pro.get('outcomesModule',{}).get('primaryOutcomes',[])})
context={'input_fingerprint':r['input_fingerprint'],'manifest_sha256':sha('input/manifest.json'),'memory':memory,'configuration':{'path':'followup_config.json','sha256':sha('followup_config.json'),'validation':'followup_validation.json','original_config_sha256':sha('analysis_config.json')},'reused_artifacts':{p:h for p,h in prior.items() if p in ['analysis.py','analysis_config.json','results.json','report.md','cohort_case_ids.json','runtime_context.json','validation.json','controller_audit.json','source_index.json','evidence_records.json','FOLLOWUP.md'] or p.startswith('mcp_artifacts/')},'reused_source_manifests':old_sources,'new_source_manifests':new,'source_requests':'Actual native MCP: two search_trials calls, kidney cancer + girentuximab and kidney cancer + NNMT; four get_trial calls. No annotation or literature request rerun. No direct API requests made by host.','search_limitations':['One page of up to 20 per concept; no pagination. Girentuximab raw response reports totalCount=20 and also has nextPageToken; preserve discrepancy and do not claim completeness.','NNMT literal intervention query returned zero; no verified NNMT agent was established in prior artifacts, so no invented drug alias was searched. Negative bounded search is not evidence of no trials.'],'statistics_rerun':['Four paired mean/t-test/95% CI/BH families with within-cohort >=80% coverage and >=20 pairs','Descriptive cross-cohort effect/rank/direction and top-100 comparisons; within-cohort cross-layer concordance and exact-four-finite-case directional check','Original exploratory selection rule reapplied, frozen candidates also reported; shortlist leave-one-out diagnostics','Input verification, memory/config agreement, cohort reconstruction and SciPy numerical checks'],'not_rerun':['Original >=20-pair-only analysis and original report/figures','UniProt/Open Targets annotation and literature retrieval','Independent scientific evaluation'],'scientific_gate':'Blocked at evaluation; no human approval or causal readiness','context_units':'UTF-8 bytes, not tokens','trial_details':trials}
save('context_sources.json',context);r['trial_evidence']=trials;r['source_context']='context_sources.json';save('followup_results.json',r)
lines=['# Stage I/II sensitivity of paired ccRCC findings','', 'Exploratory sensitivity report; independent scientific evaluation remains blocked.','', '**The main paired directions and the research shortlist persist descriptively in 37 early-stage cases. This is not independent replication, an interaction test, or proof of robustness.**','', 'The original 72-case cross-modal cohort contains 28 Stage I, 9 Stage II, 23 Stage III and 12 Stage IV cases. Exact pathological stage labels from authoritative `input/clinical_annotation.csv` retain 37 Stage I/II cases and exclude 35 later-stage cases; no stage is missing in the original cohort. Original histology/contaminated-normal exclusions and the four-assay intersection remain unchanged. No cases were added from a larger single-layer cohort.','', '## Cohort-specific gene families','', '| Cohort | Cases | Minimum finite pairs | Protein tested / q<.05 | RNA tested / q<.05 |','|---|---:|---:|---:|---:|']
for c,s in r['cohorts'].items():lines.append(f"| {c} | {s['cases']} | {s['threshold']} | {s['layers']['protein']['tested']:,} / {s['layers']['protein']['q_below_005']:,} | {s['layers']['rna']['tested']:,} / {s['layers']['rna']['q_below_005']:,} |")
lines+=['','Among 11,710 input proteins, 3,656 all-stage and 3,623 early-stage genes fail coverage. All 19,275 RNA genes meet coverage, but 260 all-stage and 360 early-stage genes have zero paired variance and are not tested. Four separate BH families include only successfully tested genes. Compared with the original 10,033-protein analysis, the new all-stage family drops 1,979 proteins due to coverage; original estimates for retained genes are unchanged, while BH q values are recalculated.','', 'The estimator remains the arithmetic mean of finite paired tumor-minus-normal differences. Protein uses processed TMT log2 reference ratios; RNA uses supplied log2 FPKM. No additional transformation or imputation. Coverage is computed independently within each cohort: max(20, ceil(0.8 × N)) = 58 or 30 pairs. Two-sided paired t tests and nominal 95% intervals use SD of paired differences / sqrt(n) and t(n−1). These are paired intervals, not independent tumor/normal intervals. They assume independent cases and sufficiently regular paired-difference means; they are neither simultaneous nor adjusted for selection. BH control depends on the usual dependence conditions, which are not established here.','', '## Effect directions and rankings','', '| Layer | Shared tested | All-only / early-only tested | Same direction | Signed / absolute effect rank rho | Top-100 absolute overlap* |','|---|---:|---:|---:|---:|---:|']
for l,c in r['comparisons'].items():lines.append(f"| {l} | {c['shared_tested']:,} | {c['all_only']} / {c['early_only']} | {100*c['same_direction_fraction']:.2f}% | {c['signed_effect_spearman']:.3f} / {c['absolute_effect_spearman']:.3f} | {c['top100_absolute_shared_universe_overlap']}/100 |")
lines+=['','*Rank correlations and top-100 sets use the shared successfully tested universe for fair descriptive comparison; ranks concern mean effects, not p values. Family-change gene lists and full estimates are in `followup_tables/`.','']
for l,c in r['comparisons'].items():lines.append(f"For {l}, among shared tested genes, {c['both_q005']:,} have q<.05 in both cohorts, {c['all_only_q005']:,} only in all-stage, and {c['early_only_q005']:,} only in early-stage. These counts mix changes in standard errors, observed effects and BH families. A difference in significance does not prove interaction, a biological stage difference, or robustness.")
lines+=['','Within-cohort RNA/protein direction agreement is 76.71% across 7,638 all-stage genes and 75.67% across 7,670 early-stage genes; descriptive cross-layer rank rho is 0.715 and 0.707. Exact same finite cases across all four assays give 76.71% and 75.75% agreement. These use different gene universes and distinct assay scales; no equality of cross-layer effects is inferred.','', '## Four prespecified genes and frozen exploratory shortlist','', 'CA9 and NNMT remain higher in both layers. MTOR total abundance remains lower in both layers; this does not establish reduced kinase activity. VEGFA RNA remains higher, while protein has one finite pair in each cohort and no valid test or interval. The two original data-selected genes, NDUFA4L2 (current UniProt COXFA4L2) and MT1H, retain their upward/downward directions. Reapplying the original selection rule (non-prespecified proteins, >=90% finite pairs, q<.05, largest absolute mean, alphabetical ties) selects them in ranks 1 and 2 in both cohorts. This selection result is exploratory and subject to winner bias; early-stage data overlap the data that selected them.','', '| Gene | Layer | Cohort | n | Mean Δ [95% CI] | p | BH q | Abs-effect rank |','|---|---|---|---:|---|---:|---:|---:|']
for x in r['shortlist']:
 fmt=lambda v: '—' if v is None else f'{v:.3g}'
 ci='not tested' if x['status']!='tested' else f"{fmt(x['mean_difference'])} [{fmt(x['ci_low'])}, {fmt(x['ci_high'])}]"
 lines.append(f"| {x['gene']} | {x['layer']} | {x['cohort']} | {x['n']} | {ci} | {fmt(x['p_value'])} | {fmt(x['q_value'])} | {fmt(x['absolute_effect_rank'])} |")
lines+=['','All testable shortlist leave-one-out means retain their direction. Medians, skew and leave-one-out ranges are saved in `followup_results.json`; this limited influence check does not establish distributional assumptions for every gene.','', '![Paired shortlist intervals](followup_figures/shortlist_comparison.png)','', '![Mean effect comparison](followup_figures/effect_comparison.png)','', '## Bounded registered-trial evidence','', 'Actual MCP ClinicalTrials.gov API v2 retrieval on 2026-09-24 used two concepts: kidney cancer + girentuximab and kidney cancer + NNMT (intervention field). Girentuximab was verified in the reused CA9 Open Targets snapshot and ARISER literature before use. No unverified aliases were introduced. One page (maximum 20 records) per concept was retrieved, followed by four selected full trial records. The girentuximab page reports 20 returned / total 20 but also supplies a next-page token; no exhaustive coverage is claimed. NNMT returned zero: this is an unsuccessful bounded literal search, not proof that no relevant trials exist. No NNMT agent was verified in the prior source artifacts.','', '| Registry record | Purpose / relevance | Phase | Source-reported status | Last update posted / status verified | Posted results |','|---|---|---|---|---|---|']
notes={'NCT00087022':'Treatment: ARISER, adjuvant antibody after nephrectomy in high-risk disease','NCT03849118':'Diagnostic imaging: ZIRCON, 89Zr-girentuximab PET/CT in indeterminate renal masses','NCT05663710':'Treatment: 177Lu-girentuximab + cabozantinib + nivolumab, advanced ccRCC','NCT05239533':'Treatment with imaging components: 177Lu-girentuximab + nivolumab, advanced ccRCC'}
for t in sorted(trials,key=lambda x:x['nct_id']):lines.append(f"| [{t['nct_id']}]({t['url']}) | {notes[t['nct_id']]} | {' / '.join(t['phase'])} | {t['status']} | {t['last_update_posted']} / {t['status_verified_date']} | {'Yes' if t['has_results'] else 'No'} |")
lines+=['','ZIRCON is a diagnostic study, with sensitivity/specificity against histology as its primary outcome; phase 3 and completion do not imply treatment efficacy. The advanced-disease combination trials are treatment research with no posted results in the retrieved snapshots; their status/phase and planned outcomes establish neither efficacy nor applicability to this early-stage tissue cohort. ARISER has posted results; the unchanged retrieved publication (PMID 27787547) reported no significant DFS advantage (HR 0.97, 95% CI 0.79–1.18) or OS advantage (0.99, 0.74–1.32). This limits extrapolation from CA9 tissue contrast to adjuvant benefit. Registry dates are source-reported and can be stale; retrieval date is not the status-verification date.','', 'Prior UniProt/Open Targets annotations and literature were reused without new requests. Kim et al. (PMID 41399267), a separate 14-patient paired RNA study with cell-line experiments, supports NNMT biological follow-up, not human efficacy. Independence of reused public multiomics data in Wang et al. (PMID 42440812) remains unresolved. No candidate-specific literature was newly obtained for NDUFA4L2 or MT1H. Original Clark/CPTAC findings are not independent replication. Full URLs, original snapshots, new raw responses, hashes, source dates and trial outcomes are indexed in `context_sources.json`; no registry outcome effect was newly estimated.','', '## Reuse, validation and continuation','', 'All nine input hashes and sizes were verified before memory retrieval or estimation; exact fingerprint: `'+r['input_fingerprint']+'`. Six original decisions were usable with no issues (4,462 UTF-8 context bytes, not tokens). Record IDs and selected keys are in `followup_memory_retrieval.json`. Retrieved cohort, scales, missingness, estimator and shortlist fields were checked against `analysis_config.json` before driving the follow-up config and cohort validation. Original code was read for method compatibility but not executed. Saved original cohort IDs, results, validation, controller, annotation and literature snapshots were reused. The original continuation note is copied byte-for-byte to `followup_initial_notes.md`.','', 'Rerun statistics: four cohort/layer paired estimates, intervals, p values and within-family BH; family/direction/rank comparisons; shortlist selection and leave-one-out diagnostics; cross-layer exact-finite-case directional sensitivity. Rerun source requests: exactly two native MCP trial searches and four trial-detail requests. Original analysis, annotation requests and literature searches were not rerun. All-stage means were checked against saved originals; BH in all four families was checked with SciPy and all testable shortlist intervals/tests with a separate SciPy calculation. Both actual new PNGs were visually inspected. Original report.html/results.json/figures and other initial scientific artifacts were hash-checked unchanged.','', 'Offline reproduction: `/tmp/biostat-rhc-analysis-env/bin/python followup_analysis.py` then `/tmp/biostat-rhc-analysis-env/bin/python followup_report.py`. This reuses frozen source snapshots and performs no network requests. Full gene tables are separate in `followup_tables/`; figures in `followup_figures/`. Runtime path and package versions are saved. The controller records actual follow-up stages and blocks evaluation; no human or independent approval was invented. A separately named sensitivity memory decision is appended with analyst attribution, leaving original decisions valid.','', 'Existing followup_memory_retrieval.json was refreshed for this session; its previous hash remains in followup_preservation.json. The original FOLLOWUP.md is archived at followup_initial_notes.md. Original scientific outputs remain byte-identical. To finalize provenance after an intentional rerun, use followup_finalize.py; this records an analyst-attributed sensitivity decision and does not grant independent review.','', '## Unresolved limitations and next review','', 'Serious: common-assay selection and abundance-dependent missingness may select observed pairs; the 80% rule does not resolve MNAR. Stage restriction changes the target population and precision; with 37 overlapping cases it is not an independent replication. Batch, purity, tissue composition, TMT compression and adjacent-normal biology remain unresolved. Nominal inference does not adjust for selecting the shortlist; correlation and direction agreement are descriptive, not evidence of stage invariance or causal mechanism. No formal stage-interaction, equivalence, clinical efficacy or causal analysis was conducted.','', 'Next: independent artifact/code review; assess stage-specific missingness, batch and purity; validate the frozen candidates using independent specimens and orthogonal assays; review full clinical publications before interpreting therapeutic relevance. Registry coverage is bounded and NNMT name/agent coverage incomplete. Technical checks and this same-session methodological review do not resolve these scientific gates.']
md='\n'.join(lines)+'\n';Path('FOLLOWUP.md').write_text(md)
# Tiny offline renderer for generated paragraphs, pipe tables, links and images.
import re
def inline(s):
 s=html.escape(s);s=re.sub(r'`([^`]+)`',r'<code>\1</code>',s);s=re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',s);s=re.sub(r'\[([^\]]+)\]\(([^)]+)\)',r'<a href="\2">\1</a>',s);return s
body=[];table=False
for line in lines:
 if line.startswith('|'):
  if not table:body.append('<div class="scroll"><table>');table=True
  if re.match(r'^\|[-|: ]+\|$',line):continue
  cells=line.strip('|').split('|');body.append('<tr>'+''.join('<td>'+inline(c.strip())+'</td>' for c in cells)+'</tr>');continue
 if table:body.append('</table></div>');table=False
 if not line:continue
 if line.startswith('!['):
  m=re.match(r'!\[(.*?)\]\((.*?)\)',line);img=base64.b64encode(Path(m[2]).read_bytes()).decode();body.append(f'<img alt="{html.escape(m[1])}" src="data:image/png;base64,{img}">')
 elif line.startswith('# '):body.append('<h1>'+inline(line[2:])+'</h1>')
 elif line.startswith('## '):body.append('<h2>'+inline(line[3:])+'</h2>')
 else:body.append('<p>'+inline(line)+'</p>')
if table:body.append('</table></div>')
Path('followup.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ccRCC stage sensitivity</title><style>body{font:16px/1.6 system-ui,sans-serif;color:#183044;max-width:1150px;margin:40px auto;padding:0 24px}h1,h2{line-height:1.2}h2{margin-top:40px}table{border-collapse:collapse;font-size:13px;width:100%}td{border-bottom:1px solid #ccd6de;padding:8px;text-align:left}tr:first-child{font-weight:bold;background:#edf3f7}.scroll{overflow:auto}img{width:100%;height:auto}code{font-size:13px;overflow-wrap:anywhere}a{color:#00679d}</style><body>'+''.join(body)+'</body></html>')
print('Rendered followup.html and FOLLOWUP.md; source manifests:',len(new))
